\begin{aligned}
x(t) &= As(t) + n(t) \\[1ex]
\varphi_{delay} &= kd\sin\theta = \frac{2\pi d}{\lambda}\sin\theta \\[1ex]
a(\theta) &= \left[\,1,\; e^{-j\frac{2\pi d}{\lambda}\sin\theta},\; e^{-j\frac{4\pi d}{\lambda}\sin\theta},\; \ldots,\; e^{-j\frac{2\pi (M-1)d}{\lambda}\sin\theta}\,\right]^T \\[1ex]
A &= \left[\,a(\theta_1),\; a(\theta_2),\; \ldots,\; a(\theta_K)\,\right]
\end{aligned}
